import random

def generate_test_case():
    n = random.randint(0, 1000)
    intervals = []
    end = 0
    for _ in range(n):
        if end >= 100000:
            break
        start = random.randint(end+1, 100000)
        end = random.randint(start, 100000)
        intervals.append([start, end])

    new_interval = [random.randint(0, 100000), random.randint(0, 100000)]
    if new_interval[0] > new_interval[1]:
        new_interval = new_interval[::-1]
    return intervals, new_interval
